/**
 * Event codes: the public part of every event link
 * (`/resources/events/<code>`). Generated by the server, 10 characters from
 * an alphabet without look-alikes (no 0/o, 1/l/i), which gives about 8e14
 * codes: far too many to find events by guessing. The code only grants
 * viewing; editing needs the separate edit key.
 */

/** The characters a code is drawn from. */
export const EVENT_CODE_ALPHABET = "abcdefghjkmnpqrstuvwxyz23456789";

/** Every event code's length. Longer than any static route segment (`new`, `presets`, `kit`, `admin`), so a code can never shadow one. */
export const EVENT_CODE_LENGTH = 10;

const CODE_PATTERN = new RegExp(`^[${EVENT_CODE_ALPHABET}]{${String(EVENT_CODE_LENGTH)}}$`);

/** True when `value` is shaped like an event code. Says nothing about whether the event exists. */
export function isEventCode(value: unknown): value is string {
  return typeof value === "string" && CODE_PATTERN.test(value);
}

/** The Liveblocks room id for an event. Its own namespace, apart from map sessions (`maps:`) and device sync (`sync:`). */
export function eventRoomIdForCode(code: string): string {
  return `events:${code}`;
}

/** Edit keys are 32 random bytes, base64url: exactly 43 characters. */
const EDIT_KEY_PATTERN = /^[A-Za-z0-9_-]{43}$/;

/** True when `value` is shaped like an edit key. */
export function isEditKey(value: unknown): value is string {
  return typeof value === "string" && EDIT_KEY_PATTERN.test(value);
}

/** The view-only link for an event. */
export function eventViewPath(code: string): string {
  return `/resources/events/${code}`;
}

/**
 * The edit link. The key rides in the URL fragment, which browsers never
 * send to a server, so it can't land in access logs or a `Referer` header.
 */
export function eventEditPath(code: string, editKey: string): string {
  return `${eventViewPath(code)}#edit=${editKey}`;
}

/** The stream overlay's path. `mode` picks one leaderboard when modes are ranked separately; `top` limits the rows. */
export function eventOverlayPath(
  code: string,
  options: { mode?: string; top?: number } = {},
): string {
  const params = new URLSearchParams();
  if (options.mode) params.set("mode", options.mode);
  if (options.top) params.set("top", String(options.top));
  const query = params.toString();
  return `${eventViewPath(code)}/overlay${query ? `?${query}` : ""}`;
}

/** Reads an edit key out of a URL fragment like `#edit=...`, or `null` when there isn't a well-formed one. */
export function editKeyFromHash(hash: string): string | null {
  const params = new URLSearchParams(hash.startsWith("#") ? hash.slice(1) : hash);
  const key = params.get("edit");
  return isEditKey(key) ? key : null;
}
